class MongoCustomerRepository(private val db: Db) : CustomerRepository {
    private val collection = "customers"

    /** The fields a change may write */
    private val fields = listOf("email", "name", "passwordHash", "active", "level", "address", "tags", "preferences", "extra", "deletedAt")

    override fun findById(id: String): Customer? {
        if (!ObjectId.isValid(id)) return null
        return db.find(collection, Document("_id", ObjectId(id)).append("deletedAt", null), limit = 1).firstOrNull()?.let { loaded(it) }
    }

    override fun list(offset: Int, limit: Int): Page<Customer> {
        val items = if (limit > 0) db.find(collection, Document("deletedAt", null), sort = Document("_id", 1), skip = offset, limit = limit).map { loaded(it) } else emptyList()
        return Page(items, db.count(collection, Document("deletedAt", null)), offset, limit)
    }

    override fun findByEmail(email: String): Customer? {
        return db.find(collection, Document("email", email).append("deletedAt", null), limit = 1).firstOrNull()?.let { loaded(it) }
    }

    override fun insert(entity: Customer): Customer {
        entity.id = entity.id ?: ObjectId().toHexString()
        entity.active = entity.active ?: true
        entity.level = entity.level ?: "basic"
        entity.createdAt = entity.createdAt ?: Instant.now()
        entity.updatedAt = entity.updatedAt ?: Instant.now()
        db.insert("Customer", collection, toDocument(entity))
        READ[entity] = Documents.copy(toDocument(entity)) as Document
        return entity
    }

    override fun update(entity: Customer): Customer {
        entity.updatedAt = Instant.now()
        val now = toDocument(entity)
        val changes = Documents.changes(READ[entity], now, fields)
        if (changes.isNotEmpty()) {
            (changes.getOrPut("\$set") { Document() } as Document)["updatedAt"] = now["updatedAt"]
            db.update("Customer", collection, Document("_id", now["_id"]), changes)
        }
        READ[entity] = Documents.copy(now) as Document
        return entity
    }

    override fun delete(entity: Customer): Unit {
        db.delete("Customer", collection, Document("_id", ObjectId(entity.id!!)))
    }

    override fun addTag(id: String, tag: String): Customer? {
        if (!ObjectId.isValid(id)) return null
        val change = Document("\$push", Document("tags", tag)).append("\$set", Document("updatedAt", Date()))
        return db.change("Customer", collection, Document("_id", ObjectId(id)).append("deletedAt", null), change)?.let { loaded(it) }
    }

    override fun removeTag(id: String, tag: String): Customer? {
        if (!ObjectId.isValid(id)) return null
        val change = Document("\$pull", Document("tags", tag)).append("\$set", Document("updatedAt", Date()))
        return db.change("Customer", collection, Document("_id", ObjectId(id)).append("deletedAt", null), change)?.let { loaded(it) }
    }

    /** The entity of a document, with the document kept to tell its changes. */
    private fun loaded(document: Document): Customer {
        val entity = fromDocument(document)
        READ[entity] = Documents.copy(toDocument(entity)) as Document
        return entity
    }

    /** The document of a Customer: what is null is left out. */
    private fun toDocument(value: Customer): Document {
        val document = Document()
        value.id?.let { document["_id"] = ObjectId(it) }
        value.email?.let { document["email"] = it }
        value.name?.let { document["name"] = it }
        value.passwordHash?.let { document["passwordHash"] = it }
        value.active?.let { document["active"] = it }
        value.level?.let { document["level"] = it }
        value.address?.let { document["address"] = addressToDocument(it) }
        value.tags?.let { document["tags"] = it }
        value.preferences?.let { document["preferences"] = preferencesToDocument(it) }
        value.extra?.let { document["extra"] = it }
        value.deletedAt?.let { document["deletedAt"] = Date.from(it) }
        value.createdAt?.let { document["createdAt"] = Date.from(it) }
        value.updatedAt?.let { document["updatedAt"] = Date.from(it) }
        return document
    }

    private fun fromDocument(document: Document): Customer =
        Customer(
            id = document["_id"]?.toString(),
            email = document["email"] as String?,
            name = document["name"] as String?,
            passwordHash = document["passwordHash"] as String?,
            active = document["active"] as Boolean?,
            level = document["level"] as String?,
            address = (document["address"] as Document?)?.let { addressFromDocument(it) },
            tags = (document["tags"] as List<*>?)?.mapNotNull { it as String? },
            preferences = (document["preferences"] as Document?)?.let { preferencesFromDocument(it) },
            extra = document["extra"],
            deletedAt = (document["deletedAt"] as Date?)?.toInstant(),
            createdAt = (document["createdAt"] as Date?)?.toInstant(),
            updatedAt = (document["updatedAt"] as Date?)?.toInstant(),
        )

    /** The document of a Customer.Address: what is null is left out. */
    private fun addressToDocument(value: Customer.Address): Document {
        val document = Document()
        value.street?.let { document["street"] = it }
        value.city?.let { document["city"] = it }
        value.zipCode?.let { document["zip code"] = it }
        value.location?.let { document["location"] = addressLocationToDocument(it) }
        return document
    }

    private fun addressFromDocument(document: Document): Customer.Address =
        Customer.Address(
            street = document["street"] as String?,
            city = document["city"] as String?,
            zipCode = document["zip code"] as String?,
            location = (document["location"] as Document?)?.let { addressLocationFromDocument(it) },
        )

    /** The document of a Customer.Address.Location: what is null is left out. */
    private fun addressLocationToDocument(value: Customer.Address.Location): Document {
        val document = Document()
        value.type?.let { document["type"] = it }
        value.coordinates?.let { document["coordinates"] = it }
        return document
    }

    private fun addressLocationFromDocument(document: Document): Customer.Address.Location =
        Customer.Address.Location(
            type = document["type"] as String?,
            coordinates = (document["coordinates"] as List<*>?)?.mapNotNull { (it as Number?)?.toDouble() },
        )

    /** The document of a Customer.Preferences: what is null is left out. */
    private fun preferencesToDocument(value: Customer.Preferences): Document {
        val document = Document()
        value.theme?.let { document["theme"] = it }
        value.newsletter?.let { document["newsletter"] = it }
        return document
    }

    private fun preferencesFromDocument(document: Document): Customer.Preferences =
        Customer.Preferences(
            theme = document["theme"] as String?,
            newsletter = document["newsletter"] as Boolean?,
        )

    private companion object {
        /** The document each entity was read from: a change writes only the fields that differ */
