package app

import app.entities.Country
import app.entities.Customer
import app.entities.Order
import app.entities.Product
import java.math.BigDecimal
import java.time.Instant
import java.time.LocalDateTime
import java.time.ZoneOffset
import java.util.UUID

/** Rows for the tests: valid values for every column, and the rows they point to. */
object Factories {
    /** A valid Customer that is not stored yet; n makes its unique values differ. */
    fun newCustomer(n: Int): Customer =
        Customer(
            email = "email-$n",
            name = "name-$n",
            passwordHash = "passwordhash-$n",
            active = true,
            level = "basic",
            address = newCustomerAddress(n),
            tags = emptyList(),
            preferences = newCustomerPreferences(n),
            extra = mapOf("n" to n),
            updatedAt = LocalDateTime.of(2026, 1, n % 28 + 1, 12, 0).toInstant(ZoneOffset.UTC),
        )

    /** A stored Customer. */
    fun addCustomer(uow: UnitOfWork, n: Int): Customer {
        val entity = newCustomer(n)
        return uow.customers.insert(entity)
    }

    /** A valid Customer.Address; n makes its values differ. */
    fun newCustomerAddress(n: Int): Customer.Address =
        Customer.Address(
            street = "street-$n",
            city = "city-$n",
            zipCode = "zipcode-$n",
            location = newCustomerAddressLocation(n),
        )

    /** A valid Customer.Address.Location; n makes its values differ. */
    fun newCustomerAddressLocation(n: Int): Customer.Address.Location =
        Customer.Address.Location(
            type = "Point",
            coordinates = emptyList(),
        )

    /** A valid Customer.Preferences; n makes its values differ. */
    fun newCustomerPreferences(n: Int): Customer.Preferences =
        Customer.Preferences(
            theme = "theme-$n",
            newsletter = true,
        )

    /** A valid Product that is not stored yet; n makes its unique values differ. */
    fun newProduct(n: Int): Product =
        Product(
            sku = "sku-$n",
            title = "title-$n",
            price = BigDecimal("${n % 10000}.50"),
            stock = n + 0.5,
            reference = UUID.fromString("00000000-0000-4000-8000-%012d".format(n)),
            picture = byteArrayOf(n.toByte()),
            related = emptyList(),
        )

    /** A stored Product. */
    fun addProduct(uow: UnitOfWork, n: Int): Product {
        val entity = newProduct(n)
        return uow.products.insert(entity)
    }

    /** A valid Order that is not stored yet; n makes its unique values differ. */
    fun newOrder(n: Int): Order =
        Order(
            number = n + 0.5,
            year = n + 0.5,
            lines = listOf(newOrderLine(n)),
            notes = listOf(newOrderNote(n)),
        )

    /** A stored Order, with the rows it points to. */
    fun addOrder(uow: UnitOfWork, n: Int): Order {
        val parent0 = addCustomer(uow, n)
        val entity = newOrder(n)
        entity.customer = parent0.id
        return uow.orders.insert(entity)
    }

    /** A valid Order.Line; n makes its values differ. */
    fun newOrderLine(n: Int): Order.Line =
        Order.Line(
            product = "%024x".format(n),
            quantity = 1 + n + 0.5,
            price = BigDecimal("${n % 10000}.50"),
            status = "pending",
        )

    /** A valid Order.Note; n makes its values differ. */
    fun newOrderNote(n: Int): Order.Note =
        Order.Note(
            text = "text-$n",
            at = LocalDateTime.of(2026, 1, n % 28 + 1, 12, 0).toInstant(ZoneOffset.UTC),
        )

    /** A valid Country that is not stored yet; n makes its unique values differ. */
    fun newCountry(n: Int): Country =
        Country(
            documentId = "id-$n",
            id = n + 0.5,
            name = "name-$n",
        )

    /** A stored Country. */
    fun addCountry(uow: UnitOfWork, n: Int): Country {
        val entity = newCountry(n)
        return uow.countries.insert(entity)
    }
}

